// Filter & Select Topic — JAC-1787 B안: 후보 배열 반환 (최대 5)
// 입력: items[0].json.items (네이버 뉴스 응답)
// 출력: filtered[] (최대 5건). selected는 filtered[0]로 호환 유지.

const BLACKLIST_DOMAINS = [
  'news.naver.com/sports',
  'dcinside.com',
  'theqoo.net',
  'pann.nate.com',
  'instiz.net',
];
const BLACKLIST_KEYWORDS = [
  '음주운전', '마약', '폭행', '사망', '장례',
  '19금', '노출', '이재명', '윤석열', '한동훈', '조국',
  '사기', '제도', '삼인', '성적', '선정적', '음란',
  '스포', '스포일러', '결말유출',
];

function stripHtml(s) {
  return (s || '').replace(/<[^>]+>/g, '').replace(/&[^;]+;/g, ' ').trim();
}

function isBlocked(item) {
  const title = stripHtml(item.title);
  const desc = stripHtml(item.description);
  const url = item.originallink || item.link || '';
  const text = (title + ' ' + desc).toLowerCase();
  if (BLACKLIST_KEYWORDS.some(k => text.includes(k))) return true;
  if (BLACKLIST_DOMAINS.some(d => url.includes(d))) return true;
  return false;
}

const input = $input.first().json;
const items = input.items || [];
const body = $('Webhook Trigger').first().json.body || {};
const keyword = body.keyword || '';

const filteredRaw = items.filter(i => !isBlocked(i));
if (filteredRaw.length === 0) {
  return [{ json: {
    error: 'no_candidates',
    reason: '네이버 검색 결과가 모두 필터링됨',
    keyword,
    total_received: items.length,
  } }];
}

// 상위 5개까지만 후보로 보관 (재시도 최대 3회 + 여유분)
const filtered = filteredRaw.slice(0, 5).map(it => ({
  title: stripHtml(it.title),
  description: stripHtml(it.description),
  source_url: it.originallink || it.link,
  pub_date: it.pubDate,
}));

const drama_guess = keyword.split(' ')[0] || '';

return [{
  json: {
    keyword,
    filtered,
    // selected: 기본 후보(filtered[0]) — 호환성 유지
    selected: { ...filtered[0], drama_guess },
    total_received: items.length,
    candidates_after_filter: filteredRaw.length,
  },
}];

// Fetch Source + Claude Draft — JAC-1787 B안
// 후보 배열을 순회하며: 출처 본문 fetch → Claude 호출 → source_irrelevant 시 다음 후보 재시도 (최대 3회)
// 출력: { ok, content, source_body_text, selected, attempt_index, attempts_log }

const MAX_ATTEMPTS = 3;
const SOURCE_BODY_MAX = 5000;
const FETCH_TIMEOUT_MS = 12000;
const CLAUDE_TIMEOUT_MS = 90000;

function stripHtmlPage(html) {
  if (!html) return '';
  // <script>, <style> 블록 제거
  let s = html.replace(/<script[\s\S]*?<\/script>/gi, ' ');
  s = s.replace(/<style[\s\S]*?<\/style>/gi, ' ');
  // <noscript>, <iframe> 등 잡음
  s = s.replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');
  // 태그 제거
  s = s.replace(/<[^>]+>/g, ' ');
  // entity 정리
  s = s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  s = s.replace(/&[a-z#0-9]+;/gi, ' ');
  // 공백 압축
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

const upstream = $input.first().json;
const filtered = upstream.filtered || [];
const keyword = upstream.keyword || '';
const webhookBody = $('Webhook Trigger').first().json.body || {};
const apiKey = webhookBody.anthropic_api_key;
const model = webhookBody.model || 'claude-sonnet-4-6';

if (!Array.isArray(filtered) || filtered.length === 0) {
  return [{ json: { ok: false, reason: 'no_candidates_input', upstream } }];
}
if (!apiKey) {
  return [{ json: { ok: false, reason: 'missing_anthropic_api_key' } }];
}

const attempts_log = [];
const candidates = filtered.slice(0, MAX_ATTEMPTS);

for (let i = 0; i < candidates.length; i++) {
  const cand = candidates[i];
  const attempt = { index: i, source_url: cand.source_url };

  // ---- 1. 출처 페이지 fetch ----
  let pageHtml = '';
  let fetchOk = false;
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: cand.source_url,
      headers: {
        'user-agent': 'Mozilla/5.0 (compatible; KStoryWorldBot/1.0; +https://kstoryworld.com)',
        'accept': 'text/html,application/xhtml+xml',
      },
      timeout: FETCH_TIMEOUT_MS,
      returnFullResponse: false,
      json: false,
    });
    pageHtml = typeof resp === 'string' ? resp : (resp?.body || JSON.stringify(resp));
    fetchOk = !!pageHtml && pageHtml.length > 0;
  } catch (e) {
    attempt.fetch_error = (e && e.message) || String(e);
  }

  if (!fetchOk) {
    attempt.outcome = 'fetch_failed';
    attempts_log.push(attempt);
    continue;
  }

  const sourceBodyText = stripHtmlPage(pageHtml).substring(0, SOURCE_BODY_MAX);
  attempt.source_body_chars = sourceBodyText.length;

  if (sourceBodyText.length < 200) {
    attempt.outcome = 'source_body_too_short';
    attempts_log.push(attempt);
    continue;
  }

  // ---- 2. Claude 호출 ----
  const drama_guess = keyword.split(' ')[0] || '';
  const userPrompt = `당신은 KStoryWorld 블로그의 K-드라마 에디터입니다. '에디터 큐레이션 톤' 스타일로 한국어와 영어 이중 언어 가이드 초안을 작성합니다. 글로벌 독자(영어권)도 한국 드라마의 매력을 이해할 수 있게 친근하고 통찰력 있는 해설을 제공합니다.

# 입력
- 검색 키워드(드라마 제목 후보): ${keyword}
- 뉴스 제목: ${cand.title}
- 뉴스 요약: ${cand.description}
- 추정 드라마: ${drama_guess}
- 출처 URL: ${cand.source_url}
- 출처 페이지 본문(원문, 일부): ${sourceBodyText}

# 작성 규칙 — 매우 중요
1. **에디터 큐레이션 톤** — 사람 에디터가 직접 큐레이션·해설한 결과처럼 작성. 정중하지만 친근한 어조.
2. **AI/자동생성 표현 절대 금지** — 다음 표현·뉘앙스를 본문/제목/슬러그/메타에 절대 포함하지 말 것:
   - 'AI', 'AI가', 'AI-generated', 'AI-curated', 'AI-powered', '자동 생성', '자동생성', '에이전트', 'GPT', 'Claude', 'LLM', '챗봇', '인공지능', 'auto-generated', 'machine-generated'
   - 'Generated:' 같은 자동 생성 메타라인 표기
   - AI disclosure 섹션도 작성하지 말 것 — 본 워크플로는 에디터 큐레이션으로 포지셔닝
3. **본인 해설/큐레이션이 80% 이상** — 뉴스 요약을 그대로 옮겨 적지 말 것. 드라마 자체에 대한 인사이트·문화적 맥락·추천 이유가 본문 핵심.
4. **스포일러 금지** — 줄거리는 1~2화 시작점까지만, 결말·반전 노출 금지.
5. 정치인 실명·범죄 단정·성인 표현·사망 관련 표현 금지.
6. 출처 표기는 글 마지막에 1회만.
7. 한국어 본문 600자 이상, 영어 본문 200단어 이상.
8. **출처 본문에 명시된 사실만 사용** — 인물명·배우명·작품명·날짜·플랫폼 정보는 반드시 출처 본문(위 'source_body_text')에 등장한 것만 인용. 출처에 없는 사실은 추측·작성 금지.
9. **출처 본문이 드라마와 무관할 경우** — 즉, 출처가 추정 드라마(${drama_guess}) 또는 검색 키워드(${keyword})와 사실적 연관이 없다고 판단되면, 본문을 작성하지 말고 다음 JSON만 반환:
   { "error": "source_irrelevant", "reason": "<짧은 이유>" }

# 출력 형식 (오직 JSON만, 마크다운 코드블록·설명 텍스트 금지)
{
  "category": "k-drama",
  "ko": {
    "title": "SEO 친화적 한국어 제목 (60자 이내, 'AI'·'자동 생성' 단어 금지)",
    "slug": "english-slug-with-hyphens",
    "meta_description": "검색결과 발췌용 한국어 요약 (160자 이내)",
    "sections": {
      "intro": "도입 단락 (드라마·플랫폼·방영 맥락, 100~150자)",
      "plot_teaser": "줄거리 티저 — 스포일러 없이 1~2화까지의 설정·갈등 (200~300자)",
      "cultural_context": "한국 문화·사회·언어적 배경 해설 (200~300자)",
      "why_watch": "이 작품을 추천하는 이유 — 연출·연기·OST·세계관 중 2~3가지 (150~250자)",
      "closing": "마무리 (50~100자)",
      "source": "출처: ${cand.source_url}"
    }
  },
  "en": {
    "title": "SEO friendly English title (under 70 chars, no 'AI' or 'auto-generated' words)",
    "slug": "english-slug-with-hyphens",
    "meta_description": "English meta for search snippets (under 160 chars)",
    "sections": {
      "intro": "Lead paragraph (drama, platform, release context — 70~120 words)",
      "plot_teaser": "Spoiler-free teaser through episodes 1~2 setup (120~180 words)",
      "cultural_context": "Korean cultural / social / linguistic context (120~180 words)",
      "why_watch": "Why we recommend this — directing, acting, OST, worldbuilding etc (90~150 words)",
      "closing": "Closing thought (40~70 words)",
      "source": "Source: ${cand.source_url}"
    }
  },
  "tags": ["k-drama", "한국드라마", "editor-curated"]
}`;

  let claudeJson = null;
  let claudeRaw = null;
  let claudeError = null;
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: {
        model,
        max_tokens: 6000,
        messages: [{ role: 'user', content: userPrompt }],
      },
      json: true,
      timeout: CLAUDE_TIMEOUT_MS,
    });
    claudeJson = resp;
    claudeRaw = resp?.content?.[0]?.text || '';
  } catch (e) {
    claudeError = (e && e.message) || String(e);
  }

  if (claudeError || !claudeRaw) {
    attempt.outcome = 'claude_call_failed';
    attempt.claude_error = claudeError;
    attempts_log.push(attempt);
    continue;
  }

  // ---- 3. Claude 응답에서 source_irrelevant 판별 ----
  let parsedDraft = null;
  let parseError = null;
  try {
    parsedDraft = JSON.parse(claudeRaw);
  } catch (e) {
    const m = claudeRaw.match(/\{[\s\S]*\}/);
    if (m) {
      try { parsedDraft = JSON.parse(m[0]); } catch (e2) { parseError = e2.message; }
    } else {
      parseError = e.message;
    }
  }

  if (parsedDraft && parsedDraft.error === 'source_irrelevant') {
    attempt.outcome = 'source_irrelevant';
    attempt.reason = parsedDraft.reason || null;
    attempts_log.push(attempt);
    continue;
  }

  // 성공 — Format & Self-Check로 전달
  attempt.outcome = parsedDraft ? 'success' : 'claude_response_parse_failed';
  attempts_log.push(attempt);

  return [{
    json: {
      ok: true,
      // 기존 'Claude Draft' 노드와 호환: content/usage 등 그대로 전달
      content: claudeJson?.content || [{ type: 'text', text: claudeRaw }],
      usage: claudeJson?.usage,
      stop_reason: claudeJson?.stop_reason,
      model: claudeJson?.model,
      // B안 신규 필드
      source_body_text: sourceBodyText,
      selected: { ...cand, drama_guess },
      attempt_index: i,
      attempts_log,
      keyword,
      claude_parse_error: parseError,
    },
  }];
}

// 모든 후보 실패
return [{
  json: {
    ok: false,
    reason: 'all_candidates_failed',
    detail: '3개 후보 모두 fetch 실패 또는 source_irrelevant',
    attempts_log,
    keyword,
  },
}];

// Format & Self-Check — 13항목 (JAC-1787 B안: 출처 본문 ⊆ 본문 13번째 추가)
// 입력: 'Fetch Source + Claude Draft' 노드 출력 (ok=true 또는 false)
// 출력: 검증 결과 + 정제된 컨텐츠 (category=k-drama, ko/en 이중 언어)

const BLOCKED_KEYWORDS = ['음주운전','마약','폭행','사망','장례','19금','노출','이재명','윤석열','한동훈','조국','사기','제도','삼인','성적','선정적','음란'];
const NO_AI_COPY_PATTERN = /(AI[- ](generated|curated|powered)|AI가\s?정리|자동\s?생성\s?콘텐츠|Generated:)/i;

const raw = $input.first().json;

// 업스트림에서 ok:false (모든 후보 실패) — 그대로 패스스루
if (raw && raw.ok === false) {
  return [{ json: {
    ok: false,
    reason: raw.reason || 'upstream_failed',
    detail: raw.detail,
    attempts_log: raw.attempts_log,
    keyword: raw.keyword,
  } }];
}

const contentText = raw?.content?.[0]?.text || '';
const sourceBodyText = raw?.source_body_text || '';

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(contentText);
} catch (e) {
  const m = contentText.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch (e2) { parseError = e2.message; }
  } else {
    parseError = e.message;
  }
}

if (!parsed) {
  return [{ json: {
    ok: false,
    reason: 'claude_response_parse_failed',
    parseError,
    raw_excerpt: contentText.substring(0, 500),
  } }];
}

const ko = parsed.ko || {};
const en = parsed.en || {};
const koSec = ko.sections || {};
const enSec = en.sections || {};

const koBodyText = [koSec.intro, koSec.plot_teaser, koSec.cultural_context, koSec.why_watch, koSec.closing].filter(Boolean).join(' ');
const enBodyText = [enSec.intro, enSec.plot_teaser, enSec.cultural_context, enSec.why_watch, enSec.closing].filter(Boolean).join(' ');

const allText = [
  ko.title, ko.slug, ko.meta_description, koBodyText,
  en.title, en.slug, en.meta_description, enBodyText,
  (parsed.tags || []).join(' '),
].filter(Boolean).join(' ');

const korean_chars = (koBodyText.match(/[\uAC00-\uD7AF]/g) || []).length;
const en_word_count = enBodyText.trim() ? enBodyText.trim().split(/\s+/).length : 0;
const blocked_kw = BLOCKED_KEYWORDS.find(k => allText.includes(k));
const ai_copy_match = allText.match(NO_AI_COPY_PATTERN);

// ---- 13. 출처 본문 토큰 ⊆ 본문 토큰 (간이 fact-anchor 검증) ----
function extractTokens(text) {
  return Array.from(new Set(
    (text || '')
      .replace(/[^\uAC00-\uD7AFa-zA-Z0-9 ]/g, ' ')
      .split(/\s+/)
      .filter(t => t.length >= 2)
  ));
}
const sourceTokens = extractTokens(sourceBodyText);
const bodyTokens = new Set(extractTokens(koBodyText + ' ' + enBodyText));
const overlapTokens = sourceTokens.filter(t => bodyTokens.has(t));
const overlap_ratio = sourceTokens.length ? overlapTokens.length / sourceTokens.length : 0;

const checks = {
  '01_category_is_k_drama': parsed.category === 'k-drama',
  '02_ko_korean_chars_min_600': korean_chars >= 600,
  '03_en_word_count_min_200': en_word_count >= 200,
  '04_ko_title_exists_under_60': !!(ko.title && ko.title.length > 0 && ko.title.length <= 60),
  '05_en_title_exists_under_70': !!(en.title && en.title.length > 0 && en.title.length <= 70),
  '06_ko_slug_exists': !!(ko.slug && ko.slug.length > 0),
  '07_en_slug_exists': !!(en.slug && en.slug.length > 0),
  '08_ko_meta_description_under_160': !!(ko.meta_description && ko.meta_description.length > 0 && ko.meta_description.length <= 160),
  '09_en_meta_description_under_160': !!(en.meta_description && en.meta_description.length > 0 && en.meta_description.length <= 160),
  '10_tags_exist_and_are_array': !!(parsed.tags && Array.isArray(parsed.tags) && parsed.tags.length > 0),
  '11_no_blocked_keywords': !blocked_kw,
  '12_no_ai_copy_pattern': !ai_copy_match,
  '13_source_body_overlap_min_15pct': overlap_ratio >= 0.15,
};
const pass = Object.values(checks).every(Boolean);
const failures = Object.entries(checks).filter(([k,v])=>!v).map(([k])=>k);

return [{
  json: {
    ok: pass,
    self_check: checks,
    self_check_failures: failures,
    self_check_summary: pass ? '13/13 통과' : `${Object.values(checks).filter(Boolean).length}/13 통과 — 미통과: ${failures.join(', ')}`,
    blocked_keyword_hit: blocked_kw || null,
    ai_copy_hit: ai_copy_match ? ai_copy_match[0] : null,
    korean_chars,
    en_word_count,
    source_body_overlap: {
      ratio: overlap_ratio,
      threshold: 0.15,
      source_token_count: sourceTokens.length,
      overlap_token_count: overlapTokens.length,
      sample_overlap_tokens: overlapTokens.slice(0, 20),
    },
    draft: parsed,
    metadata: {
      keyword: raw.keyword,
      source: raw.selected,
      attempt_index: raw.attempt_index,
      attempts_log: raw.attempts_log,
      generated_at: new Date().toISOString(),
      model: raw.model || ($('Webhook Trigger').first().json.body.model || 'claude-sonnet-4-6'),
    },
  },
}];

// Hexagon Self-Checks (#14·#15·#15a) — JAC-1893 / JAC-1895 / JAC-1896
//
// This is the canonical JS source embedded into each n8n workflow's
// "Hexagon Self-Checks" Code node (inserted between "Format & Self-Check"
// and "Return Generated Content"). Source of truth lives in this file —
// when changing logic, edit here, then re-run the patcher to update each
// workflow JSON:
//
//     python3 n8n-workflows/_lib/apply-hexagon-self-check-node.py
//
// Behavior:
//   - If `body.hexagon_id` is NOT present on the Webhook Trigger, this
//     node is a pass-through (existing #1..#13 self-check shape preserved).
//   - If `body.hexagon_id` IS present, runs:
//       #14  anchor_backlink_present       (JAC-1895)
//       #15  images_present_with_license   (JAC-1896)
//       #15a seasonal_tone_quarter_policy  (JAC-1896 spec C)
//     merges results into self_check, recomputes ok/failures/summary, and
//     on failure tags `qc_alert: true` + (best-effort) POSTs a Telegram
//     QC alert if `telegram_bot_token` + `telegram_chat_id` were supplied
//     on the webhook body.
//
// Image schema (JAC-1896 §A):
//   draft.images: [{
//     role: "hero" | "inline_1" | "inline_2" | ...,
//     source: "unsplash" | "pexels" | "pixabay" | "wikimedia" | "cc0" | "cc-by",
//     asset_id, asset_url, license, credit, seasonal_tone,
//     alt_text_ko, alt_text_en
//   }, ...]

const IMAGE_SOURCE_WHITELIST = ['unsplash','pexels','pixabay','wikimedia','cc0','cc-by'];
const REQUIRED_IMAGE_FIELDS = ['source','asset_id','license','credit','seasonal_tone'];
const REQUIRED_ALT_FIELDS = ['alt_text_ko','alt_text_en'];
const VALID_TONES = ['spring','summer','fall','winter'];
const HERO_ROLE = 'hero';
const INLINE_ROLE_PATTERN = /^inline(_\d+)?$/;

function defaultSeasonalTone(publishMonthStr) {
  const m = parseInt(String(publishMonthStr || '').slice(5, 7), 10);
  if (m >= 4 && m <= 6) return 'spring';
  if (m >= 7 && m <= 9) return 'summer';
  if (m >= 10 && m <= 12) return 'fall';
  if (m >= 1 && m <= 3) return 'winter';
  return null;
}

function nonEmpty(v) {
  return v !== undefined && v !== null && String(v).trim() !== '';
}

const upstream = $input.first().json;
const trigger = $('Webhook Trigger').first().json.body || {};
const hexagonId = trigger.hexagon_id || null;

// Pass-through: no hexagon mode → unchanged
if (!hexagonId) {
  return [{ json: upstream }];
}

// Pass-through if upstream already failed for an unrelated reason
if (upstream.ok === false && (upstream.reason || !upstream.self_check)) {
  return [{ json: upstream }];
}

const checks = Object.assign({}, upstream.self_check || {});
const draft = upstream.draft || {};
const ko = draft.ko || {};
const en = draft.en || {};
const koSec = ko.sections || {};
const enSec = en.sections || {};
const koBody = [koSec.intro, koSec.plot_teaser, koSec.cultural_context, koSec.why_watch, koSec.closing].filter(Boolean).join(' ');
const enBody = [enSec.intro, enSec.plot_teaser, enSec.cultural_context, enSec.why_watch, enSec.closing].filter(Boolean).join(' ');
const allText = [
  ko.meta_description, en.meta_description,
  koBody, enBody,
  (draft.tags || []).join(' '),
].filter(Boolean).join(' ');

// ---- 14. anchor_backlink_present ----
const anchorUrlKo = trigger.anchor_url_ko || '';
const anchorUrlEn = trigger.anchor_url_en || '';
const anchorDrama = trigger.anchor_drama || '';
const anchorSlug = (anchorUrlKo.match(/\/([^/]+)-(?:ko|en)\.(?:html|md)$/) || [])[1] || '';
const anchorBacklinkPresent = !!(
  (anchorUrlKo && allText.includes(anchorUrlKo)) ||
  (anchorUrlEn && allText.includes(anchorUrlEn)) ||
  (anchorSlug && allText.includes(anchorSlug)) ||
  (anchorDrama && allText.includes(anchorDrama))
);
checks['14_anchor_backlink_present'] = anchorBacklinkPresent;

// ---- 15. images_present_with_license (JAC-1896 spec B) ----
//   1) length >= 2 (1 hero + ≥1 inline)
//   2) exactly 1 role==='hero', ≥1 role matching /^inline(_\d+)?$/
//   3) all sources whitelisted (case-insensitive)
//   4) every image has source/asset_id/license/credit/seasonal_tone non-empty
//   5) every image has alt_text_ko + alt_text_en non-empty
const images = Array.isArray(draft.images) ? draft.images : [];
const imageFailures = [];

if (images.length < 2) imageFailures.push(`images_length_below_2_actual=${images.length}`);

const heroes = images.filter((im) => im && String(im.role || '').toLowerCase() === HERO_ROLE);
const inlines = images.filter((im) => im && INLINE_ROLE_PATTERN.test(String(im.role || '').toLowerCase()));

if (heroes.length !== 1) imageFailures.push(`hero_role_count_must_be_1_actual=${heroes.length}`);
if (inlines.length < 1) imageFailures.push(`inline_role_count_must_be_ge_1_actual=${inlines.length}`);

for (let idx = 0; idx < images.length; idx++) {
  const im = images[idx] || {};
  for (const f of REQUIRED_IMAGE_FIELDS) {
    if (!nonEmpty(im[f])) imageFailures.push(`image_${idx}_missing_${f}`);
  }
  for (const f of REQUIRED_ALT_FIELDS) {
    if (!nonEmpty(im[f])) imageFailures.push(`image_${idx}_missing_${f}`);
  }
  const src = String(im.source || '').toLowerCase();
  if (src && !IMAGE_SOURCE_WHITELIST.includes(src)) {
    imageFailures.push(`image_${idx}_source_not_whitelisted_value=${src}`);
  }
  const tone = String(im.seasonal_tone || '').toLowerCase();
  if (tone && !VALID_TONES.includes(tone)) {
    imageFailures.push(`image_${idx}_seasonal_tone_invalid_value=${tone}`);
  }
}

const imagesOk = imageFailures.length === 0;
checks['15_images_present_with_license'] = imagesOk;

// ---- 15a. seasonal_tone_quarter_policy (JAC-1896 spec C) ----
//   expected_tone = quarter(publish_month)
//   pass if hero.seasonal_tone === expected_tone
//   else fidelity exception:
//     - manifest_hero_seasonal_tone declares an off-tone hero (≠ expected_tone)
//     - AND ≥1 inline image has seasonal_tone === expected_tone
//   else fail
const expectedTone = defaultSeasonalTone(trigger.publish_month);
const manifestHeroTone = String(trigger.manifest_hero_seasonal_tone || '').toLowerCase() || null;
const hero = heroes[0] || null;
const heroTone = hero ? String(hero.seasonal_tone || '').toLowerCase() : null;
const toneFailures = [];

let seasonalToneOk;
if (!expectedTone) {
  // No publish_month supplied → cannot evaluate; treat as not-applicable pass.
  seasonalToneOk = true;
} else if (heroTone === expectedTone) {
  seasonalToneOk = true;
} else if (!hero) {
  seasonalToneOk = false;
  toneFailures.push(`no_hero_to_check_expected=${expectedTone}`);
} else {
  // Fidelity exception: must be declared in manifest AND ≥1 inline matches expected.
  const manifestDeclaresException = manifestHeroTone && manifestHeroTone !== expectedTone;
  const inlineCoversExpected = inlines.some((im) => String(im.seasonal_tone || '').toLowerCase() === expectedTone);
  if (manifestDeclaresException && inlineCoversExpected) {
    seasonalToneOk = true;
  } else {
    seasonalToneOk = false;
    if (!manifestDeclaresException) {
      toneFailures.push(
        `fidelity_exception_not_declared_in_manifest_hero=${heroTone || 'null'}_expected=${expectedTone}_manifest=${manifestHeroTone || 'null'}`
      );
    }
    if (!inlineCoversExpected) {
      toneFailures.push(`no_inline_image_with_expected_tone=${expectedTone}`);
    }
  }
}
checks['15a_seasonal_tone_quarter_policy'] = seasonalToneOk;

// ---- recompute ok / failures / summary ----
const passList = Object.values(checks);
const passCount = passList.filter(Boolean).length;
const totalCount = passList.length;
const pass = passList.every(Boolean);
const failures = Object.entries(checks).filter(([, v]) => !v).map(([k]) => k);

const result = Object.assign({}, upstream, {
  ok: pass,
  self_check: checks,
  self_check_failures: failures,
  self_check_summary: pass
    ? `${totalCount}/${totalCount} 통과`
    : `${passCount}/${totalCount} 통과 — 미통과: ${failures.join(', ')}`,
  qc_alert: !pass,
  hexagon: {
    hexagon_id: hexagonId,
    anchor_drama: anchorDrama,
    expected_seasonal_tone: expectedTone,
    manifest_hero_seasonal_tone: manifestHeroTone,
    hero_seasonal_tone: heroTone,
    image_failures: imageFailures,
    tone_failures: toneFailures,
  },
});

// ---- Auditor (QC) Telegram alert (JAC-1896 spec D) ----
// Best-effort: if the webhook body supplied bot credentials, fire a single
// alert message. We swallow errors so the workflow response is never blocked
// by Telegram outages.
const tgToken = trigger.telegram_bot_token || '';
const tgChatId = trigger.telegram_chat_id || '';
if (!pass && tgToken && tgChatId) {
  const lines = [
    `🚨 KStoryWorld QC alert — hexagon self-check failed`,
    `hexagon: ${hexagonId}`,
    `domain: ${trigger.category || 'unknown'} / anchor: ${anchorDrama || 'n/a'}`,
    `failures: ${failures.join(', ') || '(none reported)'}`,
    imageFailures.length ? `images: ${imageFailures.slice(0, 6).join('; ')}` : '',
    toneFailures.length ? `tone: ${toneFailures.join('; ')}` : '',
  ].filter(Boolean);
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${tgToken}/sendMessage`,
      body: {
        chat_id: tgChatId,
        text: lines.join('\n'),
        disable_web_page_preview: true,
      },
      json: true,
      timeout: 5000,
    });
    result.qc_alert_dispatched = 'telegram';
  } catch (e) {
    result.qc_alert_dispatched_error = (e && e.message) || String(e);
  }
}

return [{ json: result }];
